bool remanence_medium_read_at(const RemanenceMedium *medium,
                              uint64_t offset,
                              uint8_t *buffer_out,
                              size_t length,
                              RemanenceErrorCategory *error_category_out,
                              char **error_out,
                              char **error_rule_out);

